  ink: 0x070b12,
  panel: 0x0b111b,
  panelWarm: 0x17120c,
  rail: 0x111923,
  paper: 0x1c2022,
  gold: 0xd8a840,
  brass: 0xf0c36f,
  cyan: 0x7ab8d6,
  green: 0x8fd6a0,
  danger: 0xff6b57,
  violet: 0xc9a6ff,
